+  for (const [key, value] of Object.entries(query)) for (const item of Array.isArray(value) ? value : value === undefined ? [] : [value]) search.append(key, item);
+  return `/editor${project ? `/${encodeURIComponent(project)}` : ''}${search.size ? `?${search}` : ''}`;
